for (const locale of ["de", "es", "fr"] as const) {
  for (const slug of additionalPrioritySeoArticleSlugs) {
    const labels = translationLabels[locale];
    translated[locale][slug] = {
      eyebrow: labels.eyebrow,
      title: localizedTitles[locale][slug],
      description: labels.description,
      facts: [
        { value: labels.fact[0], label: labels.factLabel[0] },
        { value: labels.fact[1], label: labels.factLabel[1] },
        { value: labels.fact[2], label: labels.factLabel[2] },
      ],
      sections: translatedHeadings[locale].map((heading, index) => [heading, translatedParagraphs[locale][index]]),
    };
  }
}

